    category: '기업인증',
    excerpt: '여성기업인증 신청 자격, 서류, 심사 과정과 정부 조달 우대 혜택을 상세히 안내합니다. 여성 CEO라면 반드시 알아야 할 기업 지원 제도입니다.',
    meta_title: '여성기업인증 신청 방법 — 조건·혜택·절차 총정리',
