    title: '조달청 나라장터 공급업체 등록 방법 — 공공조달 시장 진입 가이드',
    category: '공공조달',
    excerpt: '조달청 나라장터 공급업체 등록 절차, 필요 서류, 입찰 참여 방법을 상세히 안내합니다. 정부 조달 시장에 진입하려는 중소기업 필독 가이드입니다.',
    meta_title: '조달청 나라장터 공급업체 등록 방법 — 공공조달 가이드',
