    content: `<div class="toc"><p>목차</p><ol><li>정관과 주무관청 인가의 중요성</li><li>정관 필수 기재사항 (민법 제40조)</li><li>설립 목적 작성 노하우</li><li>주무관청 선택과 협의</li><li>창립총회 의사록 작성</li><li>임원 구성과 결격 사유</li><li>주요 반려 사례와 보완 방법</li><li>인가 후 등기·후속 절차</li></ol></div>
<h2>1. 정관과 주무관청 인가의 중요성</h2>
<p>비영리사단법인 설립은 <strong>민법 제32조</strong>에 따른 주무관청의 허가가 핵심입니다. 영리법인은 정관 작성 후 등기만으로 설립이 완료되지만, 비영리법인은 정관 검토와 사업 목적 심사를 거쳐 주무관청의 인가를 받아야 비로소 등기가 가능합니다.</p>
<p>주무관청은 정관의 형식·내용·사업 계획의 공익성을 종합적으로 심사합니다. 정관 한 줄 잘못 기재로 보완 요청을 받거나 반려되는 사례가 많아, 사전에 정확하게 작성하는 것이 무엇보다 중요합니다.</p>
<div class="highlight-box">민법 제40조: 사단법인의 정관에는 다음 각 호의 사항을 기재하고 기명날인하여야 한다. 1. 목적, 2. 명칭, 3. 사무소의 소재지, 4. 자산에 관한 규정, 5. 이사의 임면에 관한 규정, 6. 사원자격의 득실에 관한 규정, 7. 존립시기나 해산사유를 정하는 때에는 그 시기 또는 사유</div>
<h2>2. 정관 필수 기재사항 (민법 제40조)</h2>
<p>민법은 사단법인 정관의 7가지 필수 기재 사항을 규정합니다. 누락 시 등기 자체가 불가합니다.</p>
<ul><li><strong>목적:</strong> 비영리 목적 사업이 명확히 기재 (예: 청소년 교육 진흥)</li><li><strong>명칭:</strong> 사단법인이라는 단어 포함 필수</li><li><strong>사무소 소재지:</strong> 주된 사무소 주소 기재 (지점은 별도)</li><li><strong>자산에 관한 규정:</strong> 자산의 종류·운용 방법</li><li><strong>이사의 임면 규정:</strong> 선임·해임 절차와 임기</li><li><strong>사원자격의 득실:</strong> 회원 가입·탈퇴·자격 상실 조건</li><li><strong>존립 시기·해산 사유:</strong> 정한 경우에만 기재 (대부분 미정)</li></ul>
<h2>3. 설립 목적 작성 노하우</h2>
<p>설립 목적은 주무관청이 가장 면밀히 심사하는 항목입니다. 다음 원칙을 따라 작성하세요.</p>
<ul><li><strong>구체적이고 명확하게:</strong> "사회 발전 기여" 같은 모호한 표현 지양</li><li><strong>비영리 목적임을 명시:</strong> 영리 목적으로 오해될 표현 피하기</li><li><strong>주무관청 소관 분야 일치:</strong> 신청할 주무관청의 사업 영역과 부합</li><li><strong>법령상 인정되는 표현:</strong> 학술·종교·자선·기예·사교 등 명시 권장</li><li><strong>사업 항목 구체화:</strong> 목적 달성을 위한 세부 사업을 별도 조항으로 나열</li></ul>
<h2>4. 주무관청 선택과 협의</h2>
<p>법인의 사업 영역에 따라 주무관청이 달라집니다. 잘못된 부처 신청은 즉시 반려됩니다.</p>
<ul><li><strong>문화체육관광부:</strong> 문화·예술·체육·종교 관련</li><li><strong>교육부:</strong> 학술·장학·교육 관련</li><li><strong>보건복지부:</strong> 사회복지·의료·아동·노인 관련</li><li><strong>환경부:</strong> 환경 보전·자연 보호 관련</li><li><strong>여성가족부:</strong> 여성·가족·청소년 관련</li><li><strong>국토교통부:</strong> 주거·교통·도시계획 관련</li><li><strong>시·도지사:</strong> 단일 지역 한정 사업 (전국 사업은 중앙 부처)</li></ul>
<p>실무 팁: 신청 전 주무관청 담당 부서에 사전 협의를 요청하면 정관·사업계획서 보완 방향에 대한 가이드를 받을 수 있어 통과율이 크게 높아집니다.</p>
<h2>5. 창립총회 의사록 작성</h2>
<p>창립총회 의사록은 정관과 함께 인가 신청의 핵심 서류입니다. 다음 사항을 빠짐없이 기재하세요.</p>
<ol><li>창립총회 일시·장소 (실제 개최 일자)</li><li>출석 발기인 명단 (최소 2인 이상, 실무상 5인 이상 권장)</li><li>의장·서기 선임</li><li>정관 채택 결의</li><li>임원 선임 결의 (이사·감사 명단)</li><li>사업계획서 및 예산안 채택</li><li>주무관청 인가 신청 위임 결의</li><li>발기인 전원 서명·날인</li></ol>
<h2>6. 임원 구성과 결격 사유</h2>
<p>임원은 비영리법인 운영의 핵심이므로 자격 검증이 엄격합니다.</p>
<ul><li><strong>이사:</strong> 3인 이상 (이사장 1명 별도 선임 가능)</li><li><strong>감사:</strong> 1인 이상 (이사·이사회와 독립)</li><li><strong>임기:</strong> 정관에 명시 (일반적으로 2~4년)</li><li><strong>결격 사유:</strong> 미성년자, 피성년후견인, 파산 후 복권되지 않은 자, 금고 이상 형 집행 종료 후 일정 기간 미경과자</li><li><strong>외국인 임원:</strong> 가능하나 일부 주무관청은 비율 제한</li></ul>
<h2>7. 주요 반려 사례와 보완 방법</h2>
<p>실무에서 자주 발생하는 반려 사례입니다. 사전에 점검하면 보완 요청 없이 통과율을 높일 수 있습니다.</p>
<ul><li><strong>설립 목적이 모호:</strong> 구체적 사업 분야와 대상 명시</li><li><strong>주무관청 소관과 불일치:</strong> 사업 분야 재검토 후 주무관청 변경</li><li><strong>정관 조항 간 모순:</strong> 임원 임기·총회 의결 정족수 등 일관성 확인</li><li><strong>사업계획서 부실:</strong> 1~3년 사업·예산 계획 구체화</li><li><strong>임원 결격 사유 미확인:</strong> 결격 사유 확인서 첨부</li><li><strong>창립총회 절차 하자:</strong> 발기인 서명 누락, 의사록 형식 미비</li></ul>
<h2>8. 인가 후 등기·후속 절차</h2>
<p>주무관청 인가증을 받으면 다음 절차를 진행합니다.</p>
<ol><li>인가증 수령 (발급일로부터 3주 이내 등기 필수)</li><li>관할 법원 법인 설립 등기 신청</li><li>법인 설립 등기 완료 (1~2주 소요)</li><li>법인 인감 신고 (법원)</li><li>법인 사업자등록 (세무서)</li><li>4대 보험 사업장 등록 (직원 채용 시)</li><li>금융기관 법인 통장 개설</li><li>주무관청에 등기 완료 보고</li></ol>
<div class="faq-section"><h2>자주 묻는 질문 (FAQ)</h2>
<div class="faq-item"><p class="faq-q">Q. 정관은 직접 작성해도 되나요, 행정사 도움이 필요한가요?</p><p class="faq-a">A. 직접 작성도 가능하나 주무관청 심사 기준에 맞추기 어려워 보완 요청이 빈번합니다. 행정사 도움을 받으면 통과율이 크게 높아지고 평균 1~2개월 시간을 절약할 수 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 주무관청에 사전 협의를 꼭 해야 하나요?</p><p class="faq-a">A. 의무는 아니지만 강력 권장합니다. 사전 협의를 통해 정관 방향, 사업 계획 적정성, 추가 서류 등을 미리 확인할 수 있어 반려 위험이 크게 줄어듭니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 창립총회 발기인은 임원이 되어야 하나요?</p><p class="faq-a">A. 발기인 전원이 임원이 될 필요는 없습니다. 발기인 중 일부가 이사·감사로 선임되며, 나머지는 일반 사원으로 남을 수 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 정관에 사업 항목을 너무 많이 넣으면 문제가 되나요?</p><p class="faq-a">A. 비영리 목적과 무관한 사업을 다수 기재하면 영리 목적으로 의심받을 수 있습니다. 핵심 사업 5~10개로 제한하고, 추후 필요 시 정관 변경으로 추가하는 것이 안전합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 주무관청 인가까지 얼마나 걸리나요?</p><p class="faq-a">A. 일반적으로 1~3개월이 소요됩니다. 정관·사업계획서가 완비되고 사전 협의가 잘 이뤄진 경우 1~2개월 내 인가를 받을 수 있으나, 보완 요청이 반복되면 3~6개월까지 길어질 수 있습니다.</p></div>
</div>
<div class="cta-box"><h3>비영리사단법인 설립, 첫 정관부터 인가까지 함께합니다</h3><p>비전행정사사무소는 정관 작성, 주무관청 사전 협의, 인가 신청, 등기까지 원스톱으로 대행합니다. 통과율 높은 정관 템플릿과 주무관청별 노하우를 보유하고 있습니다. 초기 상담 무료입니다.</p><a href="/contact">무료상담 신청하기</a></div>`
