    content: `<div class="toc"><p>목차</p><ol><li>여성기업 확인서 유효기간</li><li>갱신 신청 시점과 절차</li><li>자격 유지 핵심 요건</li><li>임원·지분 변경 시 신고 의무</li><li>갱신 시 필요 서류</li><li>주요 반려 사유와 보완</li><li>확인 취소 사례</li><li>갱신 후 활용 전략</li></ol></div>
<h2>1. 여성기업 확인서 유효기간</h2>
<p>여성기업 확인은 <strong>여성기업지원에 관한 법률 제2조</strong>에 따라 여성이 실질적으로 소유·경영하는 기업임을 정부가 공식 인정하는 제도입니다. 확인서의 유효기간은 <strong>발급일로부터 2년</strong>(기존 제도 기준)이며, 부터 일부 변경된 기준에 따라 운영되고 있습니다.</p>
<p>유효기간이 만료되면 즉시 효력이 상실되므로, 조달청 입찰 가점·정부 지원 사업·금융 우대 등의 혜택이 중단됩니다. 따라서 만료 30~60일 전 갱신 신청이 필수입니다.</p>
<div class="highlight-box">여성기업지원에 관한 법률 시행령 제3조: 여성기업의 확인 유효기간은 확인서를 발급한 날부터 2년으로 한다. 다만 갱신 신청에 의해 연장할 수 있다.</div>
<h2>2. 갱신 신청 시점과 절차</h2>
<p>갱신은 유효기간 만료 전 신청해야 합니다. 만료 후 신청은 신규 신청과 동일하게 처리됩니다.</p>
<ol><li>만료 60일 전 알림 확인 (한국여성경제인협회 통보)</li><li>여성기업 종합정보포털(wbiz.or.kr) 로그인</li><li>갱신 신청서 작성 — 변경 사항 반영</li><li>증빙 서류 업로드</li><li>심사 (약 10~20 영업일)</li><li>확인서 재발급</li></ol>
<h2>3. 자격 유지 핵심 요건</h2>
<p>유효기간 내내 다음 요건을 충족해야 합니다. 위반 시 확인 취소 사유가 됩니다.</p>
<ul><li><strong>대표자:</strong> 여성이 대표권 보유 (공동 대표인 경우 여성 대표 비율 50% 이상)</li><li><strong>지분:</strong> 여성 임원·주주의 지분이 50% 이상</li><li><strong>경영 실질성:</strong> 여성 대표가 명목상 등재가 아닌 실질 경영 수행</li><li><strong>사업 실적:</strong> 휴·폐업 상태가 아니어야 함</li><li><strong>결격 사유 없음:</strong> 부정 수급·허위 자료 제출 이력 없음</li></ul>
<h2>4. 임원·지분 변경 시 신고 의무</h2>
<p>유효기간 중에 다음 변경이 발생하면 30일 이내 변경 신고가 필요합니다.</p>
<ul><li>대표자 변경 (특히 여성 이후 남성 변경 시 즉시 자격 상실)</li><li>여성 임원 비율 변동 (50% 미만으로 감소 시 자격 상실)</li><li>주주 변경으로 여성 지분 감소</li><li>법인 형태 변경 (법인전환·합병·분할)</li><li>본점 소재지 이전 (관할 지역 변경)</li></ul>
<p>변경 신고를 누락하면 추후 갱신 심사에서 사후 적발되어 확인이 취소되거나 부정 수급으로 처분받을 수 있습니다.</p>
<h2>5. 갱신 시 필요 서류</h2>
<ul><li>여성기업 확인 갱신 신청서</li><li>법인등기부등본 (또는 사업자등록증)</li><li>주주명부 (법인의 경우)</li><li>최근 1년간 재무제표 또는 부가가치세 신고 자료</li><li>임원 명단 및 등기부등본 (변경 시)</li><li>여성 대표자 신분증 사본</li><li>법인 인감증명서 (법인의 경우)</li></ul>
<h2>6. 주요 반려 사유와 보완</h2>
<p>갱신 심사에서 실무상 자주 발생하는 반려 사유입니다. 사전에 점검하면 보완 요청 없이 한 번에 통과할 수 있습니다.</p>
<ul><li><strong>지분 비율 변동:</strong> 신규 투자 유치로 여성 지분이 50% 미만으로 떨어진 경우</li><li><strong>대표자 실질 경영 의문:</strong> 여성 대표가 실제 사무실 출근·결재 기록 부재</li><li><strong>휴업 상태:</strong> 부가가치세 신고가 0원인 분기가 다수</li><li><strong>주소 불일치:</strong> 등기상 주소와 실제 사업장 주소가 다른 경우</li><li><strong>임원 변경 미신고:</strong> 임원 변경 후 30일 경과 신고</li></ul>
<h2>7. 확인 취소 사례</h2>
<p>실무에서 자주 발생하는 확인 취소 사례를 알아두면 사전 예방이 가능합니다.</p>
<ul><li>여성 대표 명목 등재 후 남성 가족이 실질 경영 — 부정 수급</li><li>조달청 입찰 직전 형식상 여성 대표로 변경 후 낙찰 후 원복 — 적발 시 부정당업자 제재</li><li>갱신 후 즉시 남성으로 대표 변경 — 변경 신고 의무 위반</li><li>여성 지분을 차명으로 형식만 50% 이상 유지 — 자금 흐름 조사로 적발</li></ul>
<h2>8. 갱신 후 활용 전략</h2>
<p>여성기업 확인서를 단순 유지에 그치지 않고 적극 활용하면 사업 확장에 큰 도움이 됩니다.</p>
<ul><li><strong>공공조달 우대:</strong> 조달청·지자체 입찰 가점 (5~10점)</li><li><strong>중소기업 정책자금:</strong> 여성기업 전용 자금·금리 우대</li><li><strong>여성기업 박람회 참가:</strong> 국내외 박람회 부스 지원</li><li><strong>판로 개척 지원:</strong> 한국여성경제인협회 매칭 사업</li><li><strong>해외 진출 지원:</strong> 여성기업 해외 마케팅·전시 지원</li></ul>
<div class="faq-section"><h2>자주 묻는 질문 (FAQ)</h2>
<div class="faq-item"><p class="faq-q">Q. 갱신을 깜빡 잊으면 어떻게 되나요?</p><p class="faq-a">A. 유효기간 만료 후 갱신은 불가하며, 신규 신청을 다시 해야 합니다. 만료 기간 중에는 조달청 입찰 가점·정부 지원 등이 즉시 중단됩니다. 만료 60일 전 알림을 활용해 사전 준비를 권장합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 여성 대표가 임신·출산으로 일시적으로 자리를 비우면 자격이 유지되나요?</p><p class="faq-a">A. 일시적 부재(휴직)는 자격 유지에 영향이 없습니다. 다만 실질 경영권을 다른 사람에게 양도하면 부정 수급 위험이 있으므로, 위임 절차와 결재 기록을 명확히 남기세요.</p></div>
<div class="faq-item"><p class="faq-q">Q. 외국인 여성도 여성기업 확인을 받을 수 있나요?</p><p class="faq-a">A. 한국 내 사업자등록 및 거주 자격(F-2/F-5/F-6 등)이 있다면 가능합니다. 다만 외국인투자기업의 경우 별도 요건이 추가되며, 영주권자는 내국인과 동일하게 신청 가능합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 갱신 후 임원 변경이 자유로운가요?</p><p class="faq-a">A. 임원 변경은 자유로우나 여성 임원 비율이 50% 이상 유지되어야 합니다. 변경 후 30일 이내 변경 신고를 해야 하며, 미신고 시 자격 취소 위험이 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 갱신 심사에서 매출 규모도 평가하나요?</p><p class="faq-a">A. 매출 규모 자체는 평가 기준이 아니지만 휴·폐업 상태가 아닌지 확인합니다. 부가가치세 신고가 0원인 분기가 반복되면 실질 사업 운영 여부를 추가 심사받을 수 있습니다.</p></div>
</div>
<div class="cta-box"><h3>여성기업 확인 갱신, 자격 유지·관리 전문가가 함께합니다</h3><p>비전행정사사무소는 여성기업 확인 신규·갱신·변경 신고를 원스톱으로 대행합니다. 자격 유지 점검부터 부정 수급 위험 진단까지 종합 지원합니다. 초기 상담 무료입니다.</p><a href="/contact">무료상담 신청하기</a></div>`
