    content: `<div class="toc"><p>목차</p><ol><li>AML이란? 환전업자의 의무</li><li>내부통제기준의 법적 근거</li><li>내부통제기준 필수 기재사항</li><li>고객확인의무(CDD) 실무</li><li>의심거래 보고(STR) 절차</li><li>고액현금거래 보고(CTR)</li><li>거래 기록 보관 의무</li><li>위반 시 제재와 사례</li></ol></div>
<h2>1. AML이란? 환전업자의 의무</h2>
<p>AML(Anti-Money Laundering, 자금세탁방지)은 범죄 자금이 합법 자금으로 둔갑하는 것을 차단하기 위한 제도입니다. 환전업자는 외국 통화의 매입·매각 과정에서 자금 흐름을 다루므로, <strong>특정 금융거래정보의 보고 및 이용 등에 관한 법률(특정금융정보법)</strong>에 따라 강력한 AML 의무를 부담합니다.</p>
<p>환전업자가 AML 의무를 소홀히 하면 영업 정지·등록 취소뿐 아니라 형사 처벌까지 받을 수 있어, 등록 시점부터 체계적인 내부통제 시스템 구축이 필수입니다.</p>
<div class="highlight-box">특정금융정보법 제5조: 금융회사등(환전영업자 포함)은 자금세탁방지 등을 위하여 내부통제기준을 마련하고 이를 운영해야 한다. 위반 시 1억 원 이하의 과태료가 부과된다.</div>
<h2>2. 내부통제기준의 법적 근거</h2>
<p>환전업자가 마련해야 하는 내부통제기준의 법적 근거와 가이드는 다음과 같습니다.</p>
<ul><li><strong>특정금융정보법:</strong> 모든 금융회사등의 AML 의무 규정</li><li><strong>외국환거래법:</strong> 환전영업자의 등록·운영 의무</li><li><strong>금융정보분석원(FIU) 고시:</strong> AML 내부통제기준 표준 가이드</li><li><strong>국제기준(FATF 권고안):</strong> 국제 자금세탁방지 권고 사항</li></ul>
<h2>3. 내부통제기준 필수 기재사항</h2>
<p>FIU의 AML 내부통제기준 표준안을 기준으로 다음 사항이 포함되어야 합니다.</p>
<ul><li><strong>자금세탁방지 관리자 지정:</strong> 임원급 책임자 1명 (필요 시 보고책임자 별도)</li><li><strong>고객확인의무(CDD) 절차:</strong> 신원 확인·실소유자 확인 방법</li><li><strong>의심거래 식별·보고 절차:</strong> 내부 보고 단계와 FIU 보고 프로세스</li><li><strong>고액현금거래 보고 절차:</strong> 1천만 원 이상 거래 자동 보고 체계</li><li><strong>위험 기반 접근법(RBA):</strong> 고객·거래·국가별 위험 등급 분류</li><li><strong>임직원 교육 계획:</strong> 연 1회 이상 정기 교육</li><li><strong>거래 기록 보관:</strong> 5년 이상 보관 의무</li><li><strong>독립적 감사·평가 체계:</strong> 내부 감사 또는 외부 컨설팅</li></ul>
<h2>4. 고객확인의무(CDD) 실무</h2>
<p>고객확인의무(Customer Due Diligence)는 모든 환전 거래의 첫 번째 단계입니다. 거래 금액에 따라 절차가 달라집니다.</p>
<ul><li><strong>일반 CDD:</strong> 1회 100만 원 상당액 이상 환전 시 신원 확인 (여권·신분증 사본 등)</li><li><strong>강화된 CDD(EDD):</strong> 고위험 고객(PEPs, 고위험 국가 거래) — 실소유자 확인 + 거래 목적·자금 출처 확인</li><li><strong>지속적 거래 모니터링:</strong> 기존 고객의 거래 패턴 변화 감지</li><li><strong>본인 확인 수단:</strong> 신분증·여권 사본 + 본인 서명·날인</li></ul>
<h2>5. 의심거래 보고(STR) 절차</h2>
<p>STR(Suspicious Transaction Report)은 자금세탁이 의심되는 거래를 FIU에 보고하는 의무입니다. 보고 절차는 다음과 같습니다.</p>
<ol><li>임직원이 거래 중 의심 정황 발견 (분할 거래, 통상 범위 초과, 출처 불명 등)</li><li>내부 보고 (AML 관리자에게 즉시 보고)</li><li>AML 관리자 검토 및 STR 작성 결정</li><li>FIU 보고 시스템(FIU-NET)을 통해 의심거래 보고서 제출</li><li>보고 후 거래 기록 별도 보관 (5년 이상)</li></ol>
<p>중요: STR 보고 사실을 고객에게 알리는 것은 <strong>특정금융정보법 위반</strong>이며 형사 처벌 대상입니다. 보고 후 정상 거래처럼 처리해야 합니다.</p>
<h2>6. 고액현금거래 보고(CTR)</h2>
<p>CTR(Currency Transaction Report)은 일정 금액 이상의 현금 거래를 자동 보고하는 제도입니다.</p>
<ul><li><strong>보고 기준:</strong> 1회 1천만 원 이상 또는 1일 합산 1천만 원 이상 현금 거래</li><li><strong>보고 시한:</strong> 거래일로부터 30일 이내</li><li><strong>보고 방법:</strong> FIU-NET 전산 시스템 (자동 보고 가능)</li><li><strong>분할 거래 주의:</strong> 1천만 원 미만으로 의도적 분할 거래는 STR 별도 보고 사유</li></ul>
<h2>7. 거래 기록 보관 의무</h2>
<p>환전업자는 모든 거래에 대해 다음 기록을 5년 이상 보관해야 합니다.</p>
<ul><li>고객 신원 확인 자료 (신분증 사본·서명)</li><li>거래 금액·통화·환율·일시 기록</li><li>의심거래·고액현금거래 보고 기록</li><li>임직원 AML 교육 기록</li><li>내부 감사·평가 보고서</li></ul>
<h2>8. 위반 시 제재와 사례</h2>
<p>AML 의무 위반은 다음과 같이 제재됩니다.</p>
<ul><li><strong>내부통제기준 미비:</strong> 1억 원 이하 과태료</li><li><strong>의심거래 미보고:</strong> 1억 원 이하 과태료 (반복 시 영업 정지)</li><li><strong>고액현금거래 미보고:</strong> 3천만 원 이하 과태료</li><li><strong>STR 누설 (고객에게 알림):</strong> 1년 이하 징역 또는 1천만 원 이하 벌금</li><li><strong>고객확인 위반:</strong> 시정 명령 후 미이행 시 과태료</li></ul>
<div class="faq-section"><h2>자주 묻는 질문 (FAQ)</h2>
<div class="faq-item"><p class="faq-q">Q. 소규모 환전소도 AML 내부통제기준을 마련해야 하나요?</p><p class="faq-a">A. 네, 사업 규모와 무관하게 모든 환전업자는 내부통제기준을 마련해야 합니다. 다만 사업 규모에 비례한 합리적 수준의 시스템 운영이 인정됩니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. AML 관리자는 외부에 위탁할 수 있나요?</p><p class="faq-a">A. AML 관리자는 원칙적으로 임직원이어야 합니다. 다만 시스템 운영, 직원 교육, 감사 기능은 외부 컨설팅 위탁이 가능하며, 행정사·회계법인 등을 활용하는 사례가 많습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 고객이 신분증 제시를 거부하면 어떻게 하나요?</p><p class="faq-a">A. 1회 100만 원 상당액 이상 환전 시 신원 확인이 의무이므로 거래를 거절해야 합니다. 신분증을 제시하지 않는 거래는 자체로 의심거래 보고 사유가 될 수 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 외국인 고객의 신원 확인은 어떻게 하나요?</p><p class="faq-a">A. 여권 + 외국인등록증(또는 비자) 사본을 확보해야 합니다. 단기 체류자는 여권만으로도 가능하나, 정기 거래 시에는 외국인등록증 추가 확인이 안전합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. AML 교육은 어떻게 진행하나요?</p><p class="faq-a">A. 연 1회 이상 정기 교육이 의무이며, FIU 또는 전문 컨설팅 회사의 교육 프로그램을 활용할 수 있습니다. 교육 기록과 이수증을 5년간 보관해야 합니다.</p></div>
</div>
<div class="cta-box"><h3>환전업 AML 시스템, 처음부터 제대로 구축하세요</h3><p>비전행정사사무소는 환전업 등록과 AML 내부통제기준 작성·교육·정기 평가까지 원스톱으로 지원합니다. 초기 상담 무료입니다.</p><a href="/contact">무료상담 신청하기</a></div>`
