    category: '식품',
    excerpt: 'HACCP 인증을 취득한 후 사후관리 의무와 정기 평가·갱신·취소 사례를 정리했습니다. 인증을 안전하게 유지하기 위한 실무 체크리스트를 안내합니다.',
