    content: `<div class="toc"><p>목차</p><ol><li>화장품 제조업 vs 책임판매업 — 차이와 선택</li><li>등록 결격사유 — 신청 전 반드시 확인</li><li>필수 시설기준 — 작업소·보관소·시험실</li><li>시험실 면제 요건</li><li>등록 신청 서류 목록</li><li>의약품안전나라 온라인 신청 절차</li><li>처리기간과 변경 신고 의무</li><li>자주 하는 실수와 주의사항</li></ol></div>
<h2>1. 화장품 제조업 vs 책임판매업 — 차이와 선택</h2>
<p>화장품 사업을 시작하려는 분들이 가장 먼저 혼동하는 부분이 바로 <strong>화장품 제조업</strong>과 <strong>화장품 책임판매업</strong>의 구분입니다. 두 영업은 목적이 다르므로, 자신의 사업 형태에 맞는 등록을 선택해야 합니다.</p>
<ul>
<li><strong>화장품 제조업:</strong> 화장품을 직접 생산하는 공장·제조소를 운영하는 자가 등록. 시설(작업소·보관소·시험실) 요건이 핵심.</li>
<li><strong>화장품 책임판매업:</strong> 화장품을 직접 제조하지 않고 ODM/OEM을 맡기거나 수입하여 판매하는 자가 등록. 품질관리 인력 요건이 핵심.</li>
</ul>
<p>한 회사가 두 가지를 동시에 등록하는 경우도 많습니다. 직접 제조하고 직접 판매한다면 <strong>제조업 + 책임판매업을 함께 등록</strong>해야 합니다. 단순 OEM 위탁만 한다면 책임판매업 등록만으로 충분합니다.</p>
<h2>2. 등록 결격사유 — 신청 전 반드시 확인</h2>
<p>화장품 제조업 등록은 아무나 할 수 있는 것이 아닙니다. <strong>화장품법 제3조의2</strong>에서는 등록을 할 수 없는 결격사유를 명시합니다. 해당하는 경우 반려되므로, 신청 전 반드시 확인해야 합니다.</p>
<div class="highlight-box">화장품법 제3조의2(결격사유): 다음 각 호의 어느 하나에 해당하는 자는 화장품제조업 등록을 할 수 없다. 1. 정신질환자 (전문의가 적합하다고 인정하는 경우 제외) 2. 피성년후견인 또는 파산선고를 받고 복권되지 않은 자 3. 마약류의 중독자 4. 화장품법 위반으로 금고 이상의 실형 선고 후 집행이 종료되지 않은 자 5. 이 법에 따라 등록이 취소된 날부터 1년이 지나지 않은 자</div>
<p>법인의 경우 대표자뿐 아니라 <strong>임원 전원</strong>이 결격사유에 해당하지 않아야 합니다. 임원 변경으로 결격자가 포함되면 취소 사유가 되므로 주의가 필요합니다.</p>
<h2>3. 필수 시설기준 — 작업소·보관소·시험실</h2>
<p>화장품 제조업 등록의 핵심은 <strong>화장품법 시행규칙 제6조</strong>에서 정한 세 가지 시설을 갖추는 것입니다. 시설 미비는 등록 반려의 가장 흔한 사유입니다.</p>
<div class="highlight-box">화장품법 시행규칙 제6조(시설기준): 화장품제조업을 등록하려는 자는 다음의 시설을 갖추어야 한다. 1. 제조 작업을 하는 시설을 갖춘 작업소 2. 원료·자재·제품을 보관하는 보관소 3. 원료·자재·제품의 품질검사를 위한 시험실</div>
<p><strong>① 작업소</strong>는 세 가지 세부 요건을 충족해야 합니다.</p>
<ul>
<li>쥐, 해충, 먼지 등을 막을 수 있는 방충·방서 시설</li>
<li>작업대 등 제조에 필요한 시설 및 기구</li>
<li>가루가 날리는 작업실의 경우 가루 제거 시설(집진기·환기장치)</li>
</ul>
<p><strong>② 보관소</strong>는 원료·자재·완제품을 온도·습도 관리 하에 별도 보관할 수 있는 공간이어야 합니다. 작업소와 동일 공간에 있어도 되지만, 명확히 구분된 구역이어야 합니다.</p>
<p><strong>③ 시험실</strong>은 원료 입고부터 완제품 출하까지 품질검사를 진행하는 공간입니다. 다만 외부 기관 위탁 시 면제 가능합니다.</p>
<h2>4. 시험실 면제 요건</h2>
<p>소규모 화장품 제조업체에게 부담이 되는 것이 시험실 설치 비용입니다. 화장품법 시행규칙에서는 <strong>외부 기관에 품질검사를 위탁하는 경우 시험실을 갖추지 않을 수 있다</strong>고 규정합니다.</p>
<p>품질검사 위탁이 가능한 기관은 다음과 같습니다.</p>
<ul>
<li>식품의약품안전평가원 및 지방식품의약품안전청</li>
<li>「의료기기법」에 따른 의료기기시험·검사기관</li>
<li>「국가표준기본법」에 따른 시험·검사기관 중 식약처장이 인정하는 기관</li>
<li>화장품 제조업자의 위탁검사기관(식약처 지정)</li>
</ul>
<p>위탁 계약서와 위탁기관 인증서류를 신청서에 첨부하면 시험실 없이도 등록 가능합니다. 초기 자본이 부족한 소규모 창업자에게 유용한 방법입니다.</p>
<h2>5. 등록 신청 서류 목록</h2>
<p>화장품 제조업 등록 신청 시 필요한 서류를 사전에 준비해두어야 합니다. 서류 미비는 보완 요청으로 처리기간이 늘어나는 주요 원인입니다.</p>
<ul>
<li><strong>화장품제조업 등록신청서</strong> (시행규칙 별지 제1호 서식)</li>
<li><strong>시설의 명세서</strong> (작업소·보관소·시험실 도면 포함)</li>
<li><strong>법인 등기사항증명서</strong> (법인의 경우)</li>
<li><strong>사업자등록증</strong></li>
<li><strong>품질검사 위탁계약서</strong> (시험실 면제 신청 시)</li>
<li><strong>제조소 임대차계약서</strong> (임차인 경우)</li>
</ul>
<p>개인사업자의 경우 대표자 신분증 사본이 추가로 필요합니다. 법인은 임원 전원의 결격사유 해당 여부를 확인하는 서류(신원조회 동의서)가 요구될 수 있습니다.</p>
<h2>6. 의약품안전나라 온라인 신청 절차</h2>
<p>화장품 제조업 등록은 <strong>의약품안전나라(nedrug.mfds.go.kr)</strong>를 통해 온라인으로 신청하거나, 제조소 소재지를 관할하는 <strong>지방식품의약품안전청</strong>에 방문 접수도 가능합니다.</p>
<ol>
<li><strong>의약품안전나라 회원가입</strong> 이후 사업자 공인인증서 로그인</li>
<li><strong>화장품제조업 등록신청 메뉴</strong> 접속</li>
<li>신청서 작성 — 제조소 주소, 대표자 정보, 시설 명세 입력</li>
<li>첨부 서류 PDF 업로드</li>
<li>수수료 납부 (전자수입인지 또는 신용카드)</li>
<li>접수 완료 이후 관할 지방식약청 담당자 서류 심사</li>
<li>현장 실사(필요 시) 이후 등록증 발급</li>
</ol>
<p>온라인 신청이 불편하다면 관할 지방식약청에 직접 방문하거나, <a href="/contact">행정사 대행</a>을 이용하면 서류 준비부터 접수까지 원스톱으로 처리할 수 있습니다.</p>
<h2>7. 처리기간과 변경 신고 의무</h2>
<p>화장품 제조업 등록의 법정 처리기간은 <strong>15일</strong>입니다. 서류가 완비된 경우 대체로 이 기간 내 처리되지만, 현장 실사가 필요한 경우 추가 시간이 소요될 수 있습니다.</p>
<p>등록 후에는 변경사항 발생 시 <strong>30일 이내</strong>에 변경 신고를 해야 합니다. 변경 신고 대상은 다음과 같습니다.</p>
<ul>
<li>제조소 소재지·상호 변경</li>
<li>대표자 변경</li>
<li>시설의 주요 변경 (작업소 면적 변경, 시험실 신설·폐쇄 등)</li>
</ul>
<p>변경 신고를 하지 않으면 과태료 부과 대상이 됩니다. 화장품법 위반으로 등록이 취소된 경우 1년간 재등록이 불가하므로, 변경 신고는 반드시 기한 내 처리해야 합니다.</p>
<h2>8. 자주 하는 실수와 주의사항</h2>
<p>화장품 제조업 등록 시 실무에서 자주 발생하는 실수를 미리 파악하면 반려를 예방할 수 있습니다.</p>
<ul>
<li><strong>시설도면 미비:</strong> 작업소·보관소·시험실의 위치와 면적을 표시한 도면이 없으면 보완 요청</li>
<li><strong>방충·방서 시설 미흡:</strong> 방충망·틈새 봉합 없이 신청하면 현장 실사에서 지적</li>
<li><strong>제조업과 책임판매업 혼동:</strong> 두 가지 모두 필요한 경우 함께 신청하지 않으면 나중에 추가 비용 발생</li>
<li><strong>위탁계약서 미첨부:</strong> 시험실 면제를 받으려면 반드시 위탁계약서 첨부</li>
<li><strong>임대차계약서 기간 짧음:</strong> 제조소 임대차 계약 잔여 기간이 짧으면 반려 사유가 될 수 있음</li>
</ul>
<div class="faq-section"><h3>자주 묻는 질문</h3>
<div class="faq-item"><p class="faq-q">Q. 화장품 제조업 등록에 자본금 요건이 있나요?</p><p class="faq-a">A. 화장품 제조업 등록에는 별도의 최소 자본금 요건이 없습니다. 다만 시설 구비 비용(임대료, 설비 구입비)이 실질적으로 필요합니다. 시험실 위탁으로 초기 비용을 절감할 수 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 1인 창업자도 화장품 제조업을 등록할 수 있나요?</p><p class="faq-a">A. 네, 개인사업자도 등록 가능합니다. 결격사유에 해당하지 않으며 시설 요건을 갖추면 됩니다. 단, 화장품 책임판매업은 품질관리 담당자(QM) 1명 이상을 두어야 하므로 1인 운영 시 주의가 필요합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 집이나 소규모 공간에서 화장품을 만들면 등록 없이 판매할 수 있나요?</p><p class="faq-a">A. 아닙니다. 화장품법상 제조업 등록 없이 화장품을 제조하여 판매하면 형사처벌(3년 이하 징역 또는 3천만원 이하 벌금) 대상입니다. 소규모라도 반드시 등록 후 제조·판매해야 합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 작업소 면적 최소 기준이 있나요?</p><p class="faq-a">A. 화장품법상 작업소의 최소 면적 기준은 별도로 정해져 있지 않습니다. 다만 제조 품목과 생산량에 맞는 적정 면적을 갖추어야 하며, 방충·방서·분진 제거 시설을 갖출 수 있는 공간이어야 합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 해외에서 화장품 완제품을 수입하여 국내에 판매하려면 어떤 등록이 필요한가요?</p><p class="faq-a">A. 수입 판매는 화장품 제조업이 아닌 <strong>화장품 책임판매업</strong> 등록이 필요합니다. 수입 시 각 품목별로 식약처에 화장품 수입신고를 해야 하며, 기능성 화장품은 심사 또는 보고가 추가로 필요합니다.</p></div>
</div>
<div class="cta-box"><h3>화장품 제조업 등록, 처음부터 제대로 준비하세요</h3><p>비전행정사사무소는 화장품 제조업 등록 시 서류 준비부터 관할 지방식약청 접수, 현장 실사 대응까지 전 과정을 지원합니다. 시설기준 진단, 시험실 위탁 연계까지<br>초기 상담 무료 — 전화 02-363-2251, 평일 09:30~17:30 KST.</p><a href="/contact">무료상담 신청하기</a></div>`
