    content: `<div class="toc"><p>목차</p><ol><li>스포츠클럽법 제정 배경과 목적</li><li>스포츠클럽 설립 형태 및 자격 요건</li><li>등록스포츠클럽 신청 절차와 필요 서류</li><li>지정스포츠클럽 지정 기준과 요건</li><li>지정스포츠클럽 지정 절차</li><li>공공체육시설 대관: 지정스포츠클럽의 우선권</li><li>전문특화선수 육성 관련 규정</li><li>등록·지정 후 주요 의무사항</li></ol></div>
<h2>1. 스포츠클럽법 제정 배경과 목적</h2>
<p>6월 15일 제정·공포된 <strong>스포츠클럽법(법률 제18252호)</strong>은 6월 16일부터 시행되었습니다. 이 법은 지역 주민이 생애주기에 걸쳐 스포츠 활동에 참여할 수 있는 스포츠클럽을 체계적으로 육성·지원함으로써 국민의 건강 증진과 스포츠 진흥에 기여함을 목적으로 합니다(스포츠클럽법 제1조).</p>
<p>기존에는 스포츠클럽이 국민체육진흥법, 체육시설의 설치·이용에 관한 법률 등 개별 법령에 산재된 규정을 적용받아 설립·운영 근거가 불명확했습니다. 스포츠클럽법 제정으로 비로소 스포츠클럽의 법적 지위, 등록 요건, 지정 절차, 공공체육시설 사용 우선권 등이 단일 법률로 통합되었습니다.</p>
<div class="highlight-box">스포츠클럽법 제1조(목적): 이 법은 스포츠클럽의 등록·육성 및 지원에 필요한 사항을 규정하여 지역 주민이 생애주기에 걸쳐 스포츠 활동에 참여할 수 있는 여건을 조성함으로써 국민의 건강 증진과 스포츠 진흥에 이바지함을 목적으로 한다.</div>
<p>12월 문화체육관광부는 '제1차 스포츠클럽 진흥 기본계획(~)'을 확정하여, 지정스포츠클럽 확대, 전문특화선수 육성 체계 강화, 공공체육시설 연계 등 향후 5년간 스포츠클럽 정책 방향을 제시했습니다.</p>
<h2>2. 스포츠클럽 설립 형태 및 자격 요건</h2>
<p>스포츠클럽법상 스포츠클럽은 법인 또는 단체가 시장·군수·구청장에게 등록함으로써 성립합니다(제3조). 설립 형태에 따른 주요 요건은 다음과 같습니다.</p>
<ul>
<li><strong>법인:</strong> 민법상 비영리 사단법인, 재단법인 또는 특별법에 따라 설립된 법인</li>
<li><strong>단체:</strong> 대의기구(총회·이사회 등)를 갖추고 정관을 보유한 비영리 단체</li>
<li><strong>최소 회원 수:</strong> 종목별 10명 이상(스포츠클럽법 시행령 기준)</li>
<li><strong>회비 납부 구조:</strong> 정기적인 회비를 납부하는 회원 구조 필수</li>
<li><strong>영리 목적 배제:</strong> 영리를 주된 목적으로 하지 않아야 함</li>
</ul>
<p>스포츠클럽법 제2조는 스포츠클럽을 "지역 주민의 정기적인 스포츠 활동을 위하여 회원을 모집하고 제6조에 따라 등록한 법인 또는 단체"로 정의합니다. 회원제 운영과 비영리성이 핵심 요소입니다.</p>
<p>개인 사업자나 상업 목적 피트니스센터는 스포츠클럽법상 스포츠클럽으로 등록할 수 없으며, 대신 체육시설의 설치·이용에 관한 법률에 따른 체육시설업 신고·등록 제도를 이용해야 합니다. 설립 형태 선택이 이후 지정 요건과 혜택에 큰 영향을 미치므로 사전에 전문가와 검토하는 것이 안전합니다.</p>


<p><strong>스포츠클럽 설립 형태 선택부터 법인 설립, 등록 신청까지 전문 행정사가 원스톱으로 안내드립니다.</strong></p>
<p>비전행정사사무소는 비영리 사단법인 설립 경험이 풍부하며, 스포츠클럽 등록 요건 충족 여부를 먼저 검토해 드립니다.</p>
<p><strong><a href="/contact">무료 상담 신청하기</a></strong></p>


<h2>3. 등록스포츠클럽 신청 절차와 필요 서류</h2>
<p>스포츠클럽 등록은 주된 사무소 소재지 관할 시장·군수·구청장에게 신청합니다(스포츠클럽법 제6조). 등록증을 받은 클럽은 '등록스포츠클럽'으로 지정스포츠클럽 신청 자격을 갖추게 됩니다.</p>
<p>등록 신청 시 제출 서류는 다음과 같습니다.</p>
<ul>
<li><strong>정관:</strong> 명칭·목적·소재지·대표자·임원·의결기관·재정 등 포함</li>
<li><strong>연간 운영계획서:</strong> 스포츠 종목, 회원 모집 계획, 사업 일정 등 포함</li>
<li><strong>대의기구 구성 현황:</strong> 총회·이사회 등 의사결정 기구 설명서</li>
<li><strong>회원 명부 및 회비 납부 현황:</strong> 종목별 10명 이상 확인 가능한 자료</li>
<li><strong>사무소 및 체육시설 확인 서류:</strong> 임대차계약서 또는 사용승인서</li>
<li><strong>법인 설립 관련 서류(법인인 경우):</strong> 법인등기부등본, 정관 인증 사본</li>
</ul>
<p>등록 심사는 형식 요건 검토 위주로 진행되며, 처리 기간은 통상 10~20 영업일입니다. 서류 보완 요청이 있을 경우 기간이 연장될 수 있습니다. 최근 사례에서 정관 기재 사항 누락으로 보완 요청을 받은 경우가 빈번하므로, 정관 작성 단계부터 전문가 검토를 권장합니다.</p>
<h2>4. 지정스포츠클럽 지정 기준과 요건</h2>
<p>문화체육관광부장관은 등록스포츠클럽 중 일정 요건을 갖춘 클럽을 <strong>지정스포츠클럽</strong>으로 지정할 수 있습니다(스포츠클럽법 제9조). 지정스포츠클럽은 공공체육시설 우선 사용, 전문특화선수 육성 지원 등 각종 혜택을 받을 수 있어 스포츠클럽 운영의 핵심 목표가 됩니다.</p>
<p>지정스포츠클럽이 되려면 다음 요건을 모두 충족해야 합니다.</p>
<ul>
<li><strong>비영리 법인·단체:</strong> 회원이 의결권을 행사하는 대의기구 보유</li>
<li><strong>활동 실적:</strong> 스포츠클럽 설립일로부터 3년 이상 계속 활동한 실적</li>
<li><strong>체육시설:</strong> 1년 이상 사용 가능한 체육시설 보유 또는 위탁·임대 계약 체결</li>
<li><strong>지도자:</strong> 국가체육지도자 자격을 보유한 지도자 1명 이상 고용</li>
<li><strong>재정 자립도:</strong> 최근 1년 자체 수입(회비·기부금·수익활동 등) + 지방비 수입이 총수입의 50% 이상이거나 총지출이 총수입의 80% 이상</li>
<li><strong>회원 규모:</strong> 종목별 50명 이상 또는 전체 100명 이상의 다층적 회원 구조</li>
<li><strong>개방적 회원 모집:</strong> 성별·연령·장애 등을 이유로 회원 가입을 제한하지 않을 것</li>
</ul>
<div class="highlight-box">스포츠클럽법 제9조 제1항: 문화체육관광부장관은 다음 각 호의 사업을 추진하기 위하여 등록스포츠클럽 중에서 지정스포츠클럽을 지정할 수 있다. ① 학교스포츠클럽 및 학교운동부와의 연계 ② 종목별 전문선수 육성 ③ 연령·지역·성별 특성을 반영한 스포츠 프로그램 운영 ④ 장애인 선수 육성 및 맞춤 스포츠 프로그램 운영 ⑤ 기초 종목 및 비인기 종목 육성</div>
<p>지정요건 중 '3년 이상 활동 실적' 요건은 신생 클럽에게 가장 큰 장벽입니다. 따라서 지정스포츠클럽을 목표로 한다면 등록 단계부터 체계적인 운영 기록 관리가 중요합니다. 재정 자립도 요건은 최근 강화 추세로, 정부 보조금에 지나치게 의존하는 클럽은 지정 취소 위험이 있습니다.</p>
<h2>5. 지정스포츠클럽 지정 절차</h2>
<p>지정스포츠클럽 지정은 매년 문화체육관광부의 공모를 통해 이루어집니다. 문화체육관광부는 통상 연말에 다음 연도 지정 공모계획을 공고하며, 에도 12월에 공고가 게시되었습니다.</p>
<p>지정 절차는 4단계로 진행됩니다.</p>
<ul>
<li><strong>1단계 — 신청서 제출:</strong> 대한체육회에 신청서·증빙자료·경영계획서 제출</li>
<li><strong>2단계 — 서류 심사:</strong> 대한체육회가 지정요건 충족 여부 검토</li>
<li><strong>3단계 — 경영계획서 심사:</strong> 전문위원회가 향후 운영계획 적합성 심사</li>
<li><strong>4단계 — 최종 지정:</strong> 문화체육관광부장관의 최종 승인 및 지정서 발급</li>
</ul>
<p>지정서 발급 후에는 매년 운영 현황을 보고해야 하며, 요건 미달 시 지정이 취소될 수 있습니다. 경영계획서는 단순 서식 작성이 아니라 클럽의 중장기 발전 전략, 재정 계획, 회원 확대 방안 등을 구체적으로 기술해야 하므로 전문가의 도움을 받는 것이 유리합니다.</p>
<h2>6. 공공체육시설 대관: 지정스포츠클럽의 우선권</h2>
<p>스포츠클럽법의 핵심 혜택 중 하나가 공공체육시설 우선 사용권입니다. 등록스포츠클럽도 일정한 혜택을 받을 수 있지만, <strong>지정스포츠클럽으로 지정되어야 가장 강력한 대관 우선권이 적용</strong>됩니다.</p>
<p>단계별 혜택 차이는 다음과 같습니다.</p>
<ul>
<li><strong>등록스포츠클럽:</strong> 지자체 조례에 따라 공공체육시설 사용료 최대 80% 감면 가능</li>
<li><strong>지정스포츠클럽:</strong> 공공체육시설 사용료 최대 100% 감면, 우선 수의계약 체결 가능</li>
</ul>
<div class="highlight-box">스포츠클럽법 제10조(시설의 우선 사용): 지방자치단체의 장은 공공체육시설의 효율적 이용을 위하여 지정스포츠클럽에 공공체육시설을 우선하여 사용하게 할 수 있으며, 조례로 정하는 바에 따라 사용료를 감면할 수 있다.</div>
<p>실무적으로 공공체육시설 대관은 지역 체육관, 수영장, 운동장 등을 정기적으로 사용해야 하는 스포츠클럽에게 가장 큰 비용 절감 항목입니다. 일부 지자체에서는 지정스포츠클럽에게 전용 시간대를 배정하거나 우선 예약권을 부여하고 있습니다.</p>
<p>따라서 공공체육시설을 정기적으로 이용해야 하는 스포츠클럽이라면, 단순 등록에 그치지 않고 지정스포츠클럽 지정을 목표로 설립 단계부터 계획을 세우는 것이 합리적입니다. 지자체별 조례 내용이 달라 실제 감면율과 우선권 범위가 다를 수 있으므로, 설립 전 관할 지자체 체육담당 부서와 사전 협의를 권장합니다.</p>
<h2>7. 전문특화선수 육성 관련 규정</h2>
<p>스포츠클럽법 제9조 제1항은 지정스포츠클럽의 주요 역할로 '종목별 전문선수 육성'을 명시하고 있습니다. 지정스포츠클럽은 전문선수반을 운영하여 엘리트 선수를 체계적으로 육성하는 역할을 담당합니다.</p>
<p>전문특화선수 육성과 관련된 주요 지원은 다음과 같습니다.</p>
<ul>
<li><strong>전문선수반 운영 지원:</strong> 지정스포츠클럽의 전문선수반 운영비 지원</li>
<li><strong>우수 지도자 파견:</strong> 대한체육회 또는 지자체 체육회를 통한 전문 지도자 파견 지원</li>
<li><strong>학교스포츠클럽 연계:</strong> 지역 학교스포츠클럽과 연계하여 유소년 선수 발굴·육성</li>
<li><strong>장애인 선수 특화:</strong> 장애인 선수를 위한 맞춤형 프로그램 운영 지원</li>
<li><strong>기초·비인기 종목 육성:</strong> 재정 지원이 취약한 종목의 선수 육성 우선 지원</li>
</ul>
<p>문화체육관광부는 ~제1차 스포츠클럽 진흥 기본계획에서 지정스포츠클럽의 전문선수 육성 역할을 강화하고, 학교 운동부와의 이원화된 엘리트 체육 구조를 클럽 중심으로 전환하는 것을 목표로 설정했습니다. 이 정책 방향에 따라 전문선수 육성 역량을 갖춘 지정스포츠클럽에 대한 재정 지원이 점차 확대될 전망입니다.</p>
<p>전문특화선수 관련 세부 지원 규정은 문화체육관광부 고시 및 매년 발표되는 지정스포츠클럽 운영 지침에 따라 달라질 수 있으므로, 신청 전 최신 공고를 반드시 확인해야 합니다.</p>
<h2>8. 등록·지정 후 주요 의무사항</h2>
<p>스포츠클럽 등록 및 지정스포츠클럽 지정 후에도 지속적인 요건 유지 의무가 있습니다. 의무 미이행 시 등록 취소 또는 지정 취소 처분을 받을 수 있습니다.</p>
<ul>
<li><strong>변경 신고:</strong> 명칭·소재지·대표자·정관 변경 시 30일 이내 시장·군수·구청장에게 신고</li>
<li><strong>운영 현황 보고:</strong> 매년 전년도 운영 실적(회원 현황, 재정 현황, 사업 실적 등) 보고</li>
<li><strong>지도자 자격 유지:</strong> 국가체육지도자 자격 보유자 1명 이상 상시 고용 유지(지정스포츠클럽)</li>
<li><strong>회원 개방성 유지:</strong> 성별·연령·장애 등에 따른 회원 가입 차별 금지</li>
<li><strong>아동·청소년 보호:</strong> 법령 개정으로 아동·청소년 관련 범죄경력자 고용 금지 의무 부과</li>
<li><strong>재정 자립도 유지:</strong> 지정스포츠클럽은 자체 수입 비율 요건을 매년 충족해야 함</li>
</ul>
<p>특히 스포츠클럽법 개정(법률 제20078호)으로 아동·청소년 관련 범죄경력자에 대한 고용 제한 규정이 강화되었습니다. 스포츠클럽은 지도자 채용 시 범죄경력 조회를 반드시 실시해야 합니다. 이 규정은 현재도 계속 강화되는 추세이므로 최신 법령 개정 사항을 정기적으로 확인해야 합니다.</p>
<div class="faq-section"><h2>자주 묻는 질문 (FAQ)</h2>
<div class="faq-item"><p class="faq-q">Q. 스포츠클럽 등록과 지정스포츠클럽 지정은 어떻게 다른가요?</p><p class="faq-a">A. 등록스포츠클럽은 시장·군수·구청장에게 등록한 기본 자격이며, 공공체육시설 사용료 최대 80% 감면 혜택을 받습니다. 지정스포츠클럽은 문화체육관광부장관이 심사·지정하는 상위 단계로, 공공체육시설 우선 수의계약 및 최대 100% 사용료 감면, 전문선수 육성 지원 등 더 많은 혜택을 받습니다. 지정스포츠클럽이 되려면 3년 이상 활동 실적 등 추가 요건을 충족해야 합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 스포츠클럽 설립 시 법인 설립이 반드시 필요한가요?</p><p class="faq-a">A. 반드시 법인일 필요는 없습니다. 정관과 대의기구를 갖춘 단체도 등록스포츠클럽으로 등록할 수 있습니다. 다만 지정스포츠클럽 지정 및 향후 법인 전환을 고려한다면 처음부터 비영리 사단법인으로 설립하는 것이 행정 부담을 줄일 수 있습니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 지정스포츠클럽으로 지정되면 공공체육시설을 무조건 무료로 사용할 수 있나요?</p><p class="faq-a">A. 지자체 조례에 따라 최대 100%까지 감면받을 수 있지만, 모든 지자체가 100% 감면을 적용하는 것은 아닙니다. 또한 우선 수의계약이 가능하므로 경쟁 없이 시설을 사용할 수 있는 점이 큰 장점입니다. 구체적인 감면율은 관할 지자체 조례를 확인해야 합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 3년 이상 활동 실적이 없으면 지정스포츠클럽 신청이 불가능한가요?</p><p class="faq-a">A. 현재 스포츠클럽법 시행령 기준으로 3년 이상 활동 실적이 지정 요건 중 하나입니다. 따라서 신생 클럽은 먼저 등록스포츠클럽으로 운영하면서 실적을 쌓아야 합니다. 단, 문화체육관광부가 매년 지정 요건을 고시로 조정할 수 있으므로 최신 공고를 확인하는 것이 중요합니다.</p></div>
<div class="faq-item"><p class="faq-q">Q. 스포츠클럽 설립 및 지정 신청을 행정사에게 대행하면 어떤 점이 유리한가요?</p><p class="faq-a">A. 정관 작성, 법인 설립, 등록 서류 준비, 경영계획서 작성까지 복잡한 절차를 전문가가 관리하므로 누락·오류에 따른 보완 요청 가능성이 크게 줄어듭니다. 특히 지정스포츠클럽 지정 심사는 경영계획서 적합성 심사가 포함되므로, 풍부한 실무 경험을 갖춘 행정사와 함께 준비하는 것이 1차 통과율을 높입니다. 비전행정사사무소는 초기 상담을 무료로 제공합니다.</p></div>
</div>
<div class="cta-box"><h3>스포츠클럽 설립부터 지정스포츠클럽 지정까지, 전문가와 함께하세요</h3><p>비전행정사사무소는 스포츠클럽 법인 설립, 등록스포츠클럽 신청, 지정스포츠클럽 경영계획서 작성까지 원스톱으로 지원합니다.<br>초기 상담 무료 — 전화 02-363-2251, 평일 09:30~17:30 KST.</p><a href="/contact">무료상담 신청하기</a></div>`
