    category: '식품·위생업 인허가',
    excerpt: '일반음식점을 열기 전에는 「식품위생법」에 따른 영업신고가 필수입니다. 기준 시설 기준, 위생교육, 구비서류, 신고 절차부터 영업신고 후 준수 사항까지 실무 중심으로 정리합니다.',
