    meta_title: '이노비즈 인증 심사기준과 등급 체계 | 비전행정사사무소',
    meta_description: '이노비즈 인증 평가 항목별 배점과 A·B·C 등급 체계를 상세 정리합니다. 심사 절차와 탈락 대비 전략까지 확인하세요.',
