    meta_title: '의약외품 수입 품목허가 방법과 절차 | 비전행정사사무소',
    meta_description: '의약외품 수입업 허가 요건, 해외 제조원 GMP 조건, 수입 품목허가 신청 절차를 상세히 안내합니다.',
