    excerpt: '담배 수입 시 필요한 HS코드, 관세율, 개별소비세·담배소비세, 통관 절차를 정리합니다. 수입 시 발생하는 세금의 종류와 계산 방법도 안내합니다.',
    meta_title: '담배 수입 통관 절차와 HS코드 안내 | 비전행정사사무소',
