    content: `<div class="toc"><p>목차</p><ol><li>노래연습장업이란</li><li>신고 요건</li><li>금지 행위</li><li>필요 서류</li><li>입지 규제</li><li>청소년실 운영</li><li>신고 절차</li><li>자주 묻는 질문</li></ol></div>
<h2>1. 노래연습장업이란</h2>
<p>노래연습장업은 음악산업의 진흥에 관한 법률(음악산업법) 제2조 및 제18조에 따라, 방음장치가 된 시설을 갖추고 손님이 노래를 부를 수 있도록 기계·기구를 제공하는 영업입니다. 허가제가 아닌 <strong>신고제</strong>이지만, 영업 전에 관할 시·군·구청에 신고를 마치지 않으면 무신고 영업으로 처벌받으므로 시설 공사 전 입지와 시설 기준을 먼저 확인해야 합니다.</p>
<h2>2. 신고 요건</h2>
<ul><li><strong>방음시설:</strong> 각 룸 간 음이 차단되는 구조</li><li><strong>소화설비:</strong> 화재 예방을 위한 자동소화장치 또는 소화기</li><li><strong>비상구:</strong> 영업장 면적에 따른 비상구 설치</li><li><strong>조명:</strong> 10럭스 이상 조도 유지</li><li><strong>CCTV:</strong> 복도·출입구 설치 권장(일부 지자체 의무화)</li></ul>
<h2>3. 금지 행위</h2>
<p>음악산업법 제22조에 따른 금지 행위를 반드시 준수해야 하며, 위반 시 영업정지·허가 취소·형사처벌 등 제재 수위가 높습니다.</p>
<table class="comparison-table"><tr><th>금지 행위</th><th>벌칙</th></tr><tr><td>주류 판매</td><td>1년 이하 징역, 1천만 원 이하 벌금</td></tr><tr><td>18세 미만자 출입 허용(성인 영업 시)</td><td>영업정지 또는 허가 취소</td></tr><tr><td>음란물 제공</td><td>형사처벌</td></tr><tr><td>룸 내 이성 종업원 대동</td><td>영업정지</td></tr></table>
<h2>4. 필요 서류</h2>
<table class="comparison-table"><tr><th>번호</th><th>서류명</th><th>비고</th></tr><tr><td>1</td><td>노래연습장업 영업신고서</td><td></td></tr><tr><td>2</td><td>사업자등록증 사본</td><td></td></tr><tr><td>3</td><td>건물 임대차계약서</td><td></td></tr><tr><td>4</td><td>건축물대장</td><td>문화집회시설 또는 근린생활시설</td></tr><tr><td>5</td><td>소방 완비증명서</td><td>소방서 발급</td></tr><tr><td>6</td><td>위생교육 이수증</td><td>한국음악레저산업협회 등</td></tr></table>
<h2>5. 입지 규제</h2>
<p>노래연습장은 학교환경위생정화구역(초·중·고등학교로부터 200m 이내)에서는 원칙적으로 설치가 제한됩니다. 교육환경보호위원회 심의를 거쳐 예외적으로 허용될 수 있으나, 임대차계약 전에 교육청 확인을 받아두는 것이 안전합니다. 정화구역 여부는 관할 교육지원청 또는 정부24에서 사전 열람할 수 있습니다.</p>
<h2>6. 청소년실 운영</h2>
<p>청소년이 이용 가능한 노래연습장을 운영하려면 청소년 보호법에 따라 청소년 전용 공간을 성인 이용 공간과 별도로 구분하거나, 청소년 출입 시간대를 지정하여 운영해야 합니다. 청소년실과 성인실의 출입 동선을 분리하고, 주류·담배 등 청소년 유해 물품을 청소년실에 비치하지 않아야 합니다.</p>
<h2>7. 신고 절차</h2>
<ol class="step-list"><li>소방 완비증명서 발급(소방서 방문, 통상 2~5일)</li><li>위생교육 이수</li><li>관할 시·군·구청 문화체육과(또는 민원실) 방문 신고</li><li>현장 확인 후 신고증 발급(1~3영업일)</li></ol>
<h2>8. 자주 묻는 질문</h2>
<div class="faq-section"><div class="faq-item"><p class="faq-q">Q. 노래연습장과 단란주점의 차이는 무엇인가요?</p><p class="faq-a">A. 노래연습장은 음악산업법에 따른 신고 업종으로 주류 판매가 금지되며, 단란주점은 식품위생법상 허가 업종으로 주류 판매가 가능합니다. 두 업종을 혼용해 운영하면 형사처벌 대상이 됩니다.</p></div><div class="faq-item"><p class="faq-q">Q. 기존 상가에 방음 공사만 하면 바로 신고할 수 있나요?</p><p class="faq-a">A. 건축물대장상 용도가 문화집회시설 또는 근린생활시설이어야 신고가 수리됩니다. 용도가 맞지 않으면 건축법상 용도변경 절차를 먼저 거쳐야 합니다.</p></div><div class="faq-item"><p class="faq-q">Q. 소방 완비증명서는 어떻게 발급받나요?</p><p class="faq-a">A. 관할 소방서에 완공검사를 신청하면 방음·소화설비·비상구 등을 현장 점검한 후 발급합니다. 시설 공사 완료 시점에 맞춰 사전 예약하는 것이 좋습니다.</p></div><div class="faq-item"><p class="faq-q">Q. 영업자가 변경되면 재신고가 필요한가요?</p><p class="faq-a">A. 네, 대표자가 변경되면 기존 신고의 효력이 상실되므로 신규 신고 절차를 다시 밟아야 합니다. 인수 계약서와 신규 사업자등록증을 함께 준비합니다.</p></div><div class="faq-item"><p class="faq-q">Q. 청소년실 없이 성인 전용으로만 운영할 수 있나요?</p><p class="faq-a">A. 가능합니다. 다만 출입구에 청소년 출입 제한 표시를 게시하고, 신분 확인 절차를 통해 미성년자 출입을 실질적으로 차단해야 합니다.</p></div></div>
<div class="cta-box"><h3>노래연습장 영업신고, 소방 절차부터 신고증 수령까지</h3><p>비전행정사사무소는 노래연습장 영업신고, 소방 완비증명 절차 대행, 건축물 용도변경까지 원스톱으로 지원합니다.<br>초기 상담 무료 — 전화 02-363-2251, 평일 09:30~17:30 KST.</p><a href="/contact">무료상담 신청하기</a></div>`
